using System;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using WpfColor = System.Windows.Media.Color;

namespace AVES.Core
{
    /// <summary>
    /// Shared AVES design tokens (colors, fonts, brush helpers, brand logo).
    /// Consolidated from the "Av" class (Cmds_Button7.cs, Cmds_Button8.cs,
    /// Cmds_PullDown.cs), "AvesUiHelper" (Cmds_PullDown2.cs), "AvesUI"
    /// (Cmds_Pulldown3.cs) and "T" (Cmds_Pulldown4.cs). All four sources agree
    /// on every hex value and font below.
    /// </summary>
    internal static class AvTokens
    {
        // -- Color tokens --------------------------------------------------
        public const string Accent = "#E64A2E";
        public const string AccentDeep = "#C2402A";
        public const string AccentTint = "#FBE9E4";
        public const string Surface = "#FFFFFF";
        public const string Surface2 = "#FAFAFB";
        public const string Border = "#E5E6EA";
        public const string BorderStrong = "#D4D6DC";
        public const string Text = "#1F2329";
        public const string TextDim = "#5A6069";
        public const string TextFaint = "#8B9099";
        public const string Zebra = "#F7F8FA";

        // Only Cmds_PullDown2.cs's AvesUiHelper defined this token (used as a
        // window/page background). Kept here so PullDown2 doesn't need its own
        // leftover token class after migration.
        public const string Backdrop = "#F4F4F6";

        // -- Status-pill tokens ---------------------------------------------
        // Present as named constants in AvesUiHelper, AvesUI and T (Av's copies
        // hardcoded the same hex values inline in StatusPill's switch instead of
        // naming them). Values agree everywhere they appear.
        public const string OkBg = "#E4F3EA"; public const string OkFg = "#2C7A52";
        public const string SkipBg = "#EDEFF2"; public const string SkipFg = "#5B6573";
        public const string FailBg = "#FBE3DE"; public const string FailFg = "#C0381F";
        public const string WarnBg = "#FAF0DA"; public const string WarnFg = "#9A6B12";
        public const string InfoBg = "#E7EFFB"; public const string InfoFg = "#2E66A8";

        // -- Fonts ------------------------------------------------------------
        public static readonly FontFamily Ui = new FontFamily("Segoe UI");
        public static readonly FontFamily Mono = new FontFamily("Consolas");

        // -- Brush helpers ----------------------------------------------------
        // B/Br/Brush are aliases for the same conversion, kept side by side so
        // each command file's call sites (which used different original names)
        // can switch to AvTokens by changing only the class-name prefix, not the
        // method name, during the Phase 3 migration.
        public static WpfColor Hex(string hex) => (WpfColor)ColorConverter.ConvertFromString(hex);
        public static SolidColorBrush B(string hex) => new SolidColorBrush(Hex(hex));
        public static SolidColorBrush Br(string hex) => B(hex);
        public static SolidColorBrush Brush(string hex) => B(hex);

        // -- Brand logo (decoded from embedded Base64 PNG) ---------------------
        // Canonical 248x90 asset, agreed by Av (Cmds_Button7.cs, Cmds_Button8.cs),
        // AvesUiHelper (Cmds_PullDown2.cs) and T (Cmds_Pulldown4.cs).
        // NOTE: Cmds_Pulldown3.cs's AvesUI class instead embedded a different,
        // lower-resolution 75x28 crop of the same logo. Per the reviewed decision,
        // Pulldown3 converges on this asset during its migration (Phase 3) --
        // a small, disclosed visual change to that file's title bar, not a silent one.
        public const string LogoBase64 = "";

        private static ImageSource? _logoImage;

        /// <summary>Cached decoded logo bitmap. Frozen, safe to share across windows.</summary>
        public static ImageSource LogoImage
        {
            get
            {
                if (_logoImage != null) return _logoImage;
                var bytes = Convert.FromBase64String(LogoBase64);
                using var ms = new System.IO.MemoryStream(bytes);
                var bmp = new BitmapImage();
                bmp.BeginInit();
                bmp.CacheOption = BitmapCacheOption.OnLoad;
                bmp.StreamSource = ms;
                bmp.EndInit();
                bmp.Freeze();
                _logoImage = bmp;
                return _logoImage;
            }
        }
    }
}
